"""Block input construction for this platform.

Generated by the factory WRITER. Handlers call prepare_block_input (via the
fail-closed execute wrapper) so domain records become block-acceptable
payloads without requiring the caller to know about channel/steps/paths.
"""

from __future__ import annotations

import json
import os
import re
import tempfile
from typing import Any, Dict, List, Optional, Sequence, Tuple

STORE_BLOCK_DEFAULT_ACTIONS = {'analytics': 'track_event', 'audit': 'log', 'capture': 'extract', 'capture_v2': 'extract', 'dashboard': 'render', 'database': 'query', 'document_engine': 'parse', 'event_bus': 'publish', 'formula_executor': 'execute', 'formula_executor_v2': 'execute', 'notification': 'send', 'queue': 'enqueue', 'team': 'create_team', 'validation': 'validate', 'vector_search': 'search', 'workflow': 'run', 'spec_analyzer': 'analyze', 'recommendation_template': 'apply_template', 'readiness_engine': 'score', 'storage': 'store', 'estate_registry': 'register', 'estate_maintenance': 'plan_work', 'evidence_verifier': 'verify', 'portfolio_rollup': 'aggregate', 'knowledge': 'search'}


def default_block_action(block_id, default_actions=None):
    """Keyword action for execute(..., action=). Never invent from payload."""
    bid = str(block_id or "").strip()
    if isinstance(default_actions, dict):
        cand = default_actions.get(bid)
        if isinstance(cand, str) and cand.strip():
            return cand.strip()
    mapped = STORE_BLOCK_DEFAULT_ACTIONS.get(bid)
    if isinstance(mapped, str) and mapped.strip():
        return mapped.strip()
    return None


_QUEUE_INT_KEYS = (
    "id",
    "priority",
    "delay",
    "delay_seconds",
    "timeout",
    "visibility_timeout",
    "attempts",
    "max_attempts",
    "retry_count",
    "item_id",
)
_DOC_PATH_KEYS = (
    "file_path",
    "pdf_path",
    "docx_path",
    "xlsx_path",
    "attachment_path",
    "document_path",
    "path",
)
_TEAM_STRING_KEYS = ("user_id", "name", "slug", "role", "email", "plan", "permission")
_TOPIC_KEYS = ("topic", "event", "event_type", "event_name", "reminder_type")
_MINIMAL_PDF = (
    b"%PDF-1.1\n"
    b"1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj\n"
    b"2 0 obj<</Type/Pages/Kids[3 0 R]/Count 1>>endobj\n"
    b"3 0 obj<</Type/Page/MediaBox[0 0 3 3]>>endobj\n"
    b"trailer<</Size 4/Root 1 0 R>>\n"
)
_SYNTH_DOC_PATH = None
_SKIP = frozenset(
    {
        "ok",
        "error",
        "capability",
        "id",
        "status",
        "result",
        "results",
        "payload",
        "action",
        "block",
        "blocks",
