        "/v1/rag/ingest",
        "/v1/steward/rag/ingest",
        "/v1/dual_rag_sop",
        "/v1/dual_rag_estate_docs",
    )
    planted = False
    for path in ingest_paths:
        resp = http.request(
            "post",
